const $=s=>document.querySelector(s);const storageKey='reroute-island-v1';let state;try{state=JSON.parse(localStorage.getItem(storageKey))}catch{}state=state||{day:1,completed:[],events:[],restDays:[]};let activeRoute=null,timer=null,remaining=0,view='island';const routes=[{id:'explore',icon:'♧',tag:'THE SCENIC ROUTE',name:'A little fresh air',description:'Step outside. Leave the to-do list behind for a little while.',minutes:10,context:'Outdoors',cta:'Take the scenic route',strategy:'The fresh-air reset',symbol:'♧'},{id:'shortcut',icon:'⌁',tag:'SMALL IS STILL SOMETHING',name:'Small steps, right here',description:'A gentle indoor movement break. Make the space you have work.',minutes:3,context:'Indoors',cta:'Find a little shortcut',strategy:'The indoor shortcut',symbol:'⌁'},{id:'together',icon:'♧♧',tag:'BETTER WITH COMPANY',name:'A walk & a catch-up',description:'Ask someone nearby to join you. A little movement, a little connection.',minutes:8,context:'With a friend',cta:'Choose the together route',strategy:'The company you keep',symbol:'☷'}];const detours={time:{name:'The tiny window',description:'Try a two-minute indoor movement break when a gap opens up. Choose a comfortable pace.',minutes:2,context:'Busy day · Indoors',symbol:'⌛',why:'A shorter option can fit into the time you have. You decide when to try it.'},energy:{name:'The gentle route',description:'Try one minute of comfortable seated movement, or choose rest if that feels better.',minutes:1,context:'Low energy · Seated',symbol:'☁',why:'You told us your energy is low. This option changes the effort as well as the duration.'},weather:{name:'A change of scenery',description:'Take a three-minute indoor wander, away from the weather. A hallway works too.',minutes:3,context:'Weather changed · Indoors',symbol:'☂',why:'Keep the movement you wanted, in a different setting.'},location:{name:'Room to move',description:'Try two minutes of gentle seated movement wherever you feel comfortable.',minutes:2,context:'Different space · Seated',symbol:'⌂',why:'You don’t need a usual route or a big space. Choose movements that suit you.'}};function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('Storage unavailable. Progress lasts for this visit.')}}function log(title,description){state.events.unshift({day:state.day,title,description});save()}function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500)}function open(html){stopTimer();$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function close(){stopTimer();$('#modal').close()}function stopTimer(){if(timer)clearInterval(timer);timer=null}function btn(label,action,cls=''){return `<button class="full-btn ${cls}" data-action="${action}">${label}</button>`}function completedToday(){return state.completed.some(x=>x.day===state.day)}function render(){const unique=new Set(state.completed.map(x=>x.id));$('#discoveries').textContent=unique.size;$('#day-label').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('#path-count').textContent=`${unique.size} ${unique.size===1?'path':'paths'} discovered`;$('#route-grid').innerHTML=routes.map(r=>`<article class="route-card"><div class="card-top"><span class="route-icon">${r.icon}</span><span class="route-tag">${r.tag}</span></div><h3>${r.name}</h3><p>${r.description}</p><div class="route-meta">◷ ${r.minutes} min <span>·</span> ${r.context}</div><button class="route-button" data-route="${r.id}">${completedToday()?'Already explored today':' '+r.cta}<span>${completedToday()?'✓':'↗'}</span></button></article>`).join('');$('#map-message').textContent=completedToday()?'A little movement. A new piece of your world.':state.restDays.includes(state.day)?'A quiet day is part of the journey.':'Every small step opens a new path.';$('#map-sub').textContent=state.restDays.includes(state.day)?'Your island will be right here when you’re ready.':'Your island grows with you. It never resets.';renderIsland();if(view==='collection')renderCollection();if(view==='journal')renderJournal()}
function setView(v){view=v;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));['island','collection','journal'].forEach(x=>$(`#${x}-view`).hidden=x!==v);if(v==='collection')renderCollection();if(v==='journal')renderJournal()}
function renderCollection(){const unique=[...new Map(state.completed.map(x=>[x.id,x])).values()];$('#collection-view').innerHTML=`<div class="eyebrow">YOUR PERSONAL PLAYBOOK</div><h1>Little discoveries. Lasting paths.</h1><p>These are strategies you’ve tried in real life. Keep the ones that fit.</p>${unique.length?`<div class="discovery-grid">${unique.map(r=>{const times=state.completed.filter(x=>x.id===r.id).length;return `<article class="discovery-card"><span class="symbol">${r.symbol}</span><h3>${r.strategy||r.name}</h3><p>${r.context}</p><span class="pill">${times>1?`USED ${times} TIMES`:'TRIED ONCE'}</span><p>${times>1?'A familiar option to try again.':'An early discovery. Keep exploring what works for you.'}</p><button class="route-button" data-replay="${r.id}">Try this route again <span>↗</span></button></article>`}).join('')}</div>`:`<div class="empty"><div class="success-art">⌁</div><h2>Your first discovery is out there.</h2><p>Complete a daily route or a detour to add it to your collection.</p><button class="text-btn" data-action="home">Find a route →</button></div>`}`}
function renderJournal(){const days=new Set(state.completed.map(x=>x.day)).size,minutes=state.completed.reduce((a,x)=>a+x.minutes,0);$('#journal-view').innerHTML=`<div class="eyebrow">PROGRESS THAT DOESN’T DISAPPEAR</div><h1>Your journey, detours included.</h1><p>A record of movement, discoveries, and the days you chose to pause.</p><div class="stats"><div class="stat"><strong>${minutes}</strong><span>Minutes completed*</span></div><div class="stat"><strong>${days}</strong><span>Days with movement</span></div><div class="stat"><strong>${state.completed.filter(x=>x.detour).length}</strong><span>Detours completed</span></div></div><p style="font-size:10px">*Self-reported or simulated in this prototype. Pauses and reflections don’t count as movement.</p>${state.events.length?state.events.map(e=>`<div class="journal-item"><span class="journal-day">DAY ${String(e.day).padStart(2,'0')}</span><div><h3>${e.title}</h3><p>${e.description}</p></div></div>`).join(''):'<div class="empty"><h2>A fresh page for your adventure.</h2><p>Your journey begins with your first route.</p></div>'}`}
function chooseRoute(id){if(completedToday()){open(`<div class="modal-icon">✧</div><h2>You’ve found a path today.</h2><p>Take a moment to enjoy it. Try a new demo day to explore how your island grows over time.</p>${btn('Try a new day','next')}${btn('Back to my island','close','quiet-btn')}`);return}activeRoute=routes.find(r=>r.id===id)||state.completed.find(r=>r.id===id);routeDetails()}
function routeDetails(){const r=activeRoute;open(`<span class="pill">${r.detour?'A NEW WAY FORWARD':'YOUR CHOSEN ROUTE'}</span><div class="modal-icon" style="margin-top:22px">${r.symbol||r.icon}</div><h2>${r.name}</h2><p>${r.description}</p><p>◷ ${r.minutes} minutes · ${r.context}</p>${r.detour?`<div class="detour-box"><strong>Why this route?</strong><p>${r.why}</p></div>`:''}${btn('Let’s give it a go →','start')}${btn('Plans changed','barriers','secondary-btn')}${btn('Maybe later','close','quiet-btn')}<p style="font-size:10px">Choose a comfortable activity that suits your abilities. You can stop or rest at any time.</p>`)}
function start(){remaining=activeRoute.minutes*60;open(`<span class="pill">${activeRoute.detour?'TAKING A DETOUR':'A LITTLE TIME FOR YOU'}</span><h2>${activeRoute.name}</h2><p>Your route is ready. Put your phone down and enjoy a little movement.</p><div class="timer" id="timer"></div><div class="timer-note">You can pause, change plans, or stop whenever you need.</div>${btn('Pause timer','pause')}${btn('I finished my movement','finish','secondary-btn')}${btn('Plans changed','barriers','quiet-btn')}<button class="full-btn quiet-btn" data-action="simulate">Prototype: simulate completion ↗</button>`);tick();timer=setInterval(()=>{remaining=Math.max(0,remaining-1);tick();if(!remaining){stopTimer();$('#timer').textContent='Ready ✓';const b=$('[data-action="pause"]');if(b)b.disabled=true}},1000)}function tick(){if($('#timer'))$('#timer').textContent=`${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}`}
function barriers(){activeRoute=activeRoute||routes[0];open(`<span class="pill">LIFE HAPPENS. WE CAN REROUTE.</span><h2>What changed?</h2><p>One tap helps us suggest a different way. Your progress stays right where it is.</p><div class="barriers"><button class="barrier" data-barrier="time"><span>⌛</span>Time got away</button><button class="barrier" data-barrier="energy"><span>☁</span>Low on energy</button><button class="barrier" data-barrier="weather"><span>☂</span>Weather changed</button><button class="barrier" data-barrier="location"><span>⌂</span>Different space</button></div>${btn('I’d rather rest today','rest','secondary-btn')}${btn('Back to my route','details','quiet-btn')}`)}
function detour(key){activeRoute={...detours[key],id:'detour-'+key,detour:true,strategy:detours[key].name};routeDetails()}
function finish(simulated){if(completedToday())return;const r={...activeRoute,day:state.day,simulated};state.completed.push(r);log(r.detour?'A detour became a discovery':`${r.name} completed`,`${simulated?'Demo simulation':'Self-reported'} · ${r.minutes} minutes · ${r.context}.`);render();open(`<span class="pill">A NEW PATH, AT YOUR PACE</span><div class="success-art">🌿</div><h2>${r.detour?'You found another way.':'Look how far a little goes.'}</h2><p>${r.detour?'Your detour is now part of your island. It’s a route you can come back to when life changes.':'A new path is yours. Every small action adds to your world, and none of it disappears after a missed day.'}</p><div class="detour-box"><strong>Discovery unlocked: ${r.strategy||r.name}</strong><p>Tried once · ${r.context}</p></div>${simulated?'<p style="font-size:11px">This was a simulated completion for the prototype.</p>':''}${btn('See my island →','close')}${btn('Open my discoveries','collection','quiet-btn')}`)}
function rest(){open(`<div class="modal-icon">☾</div><h2>A softer route today.</h2><p>Rest is welcome here. Your island and discoveries stay exactly as they are. No catching up required.</p>${btn('Choose rest today','confirm-rest')}${btn('Find a different route','barriers','quiet-btn')}`)}function next(){state.day++;save();close();setView('island');render();toast('A fresh day. Every path you’ve found is still yours.')}
function reset(){open(`<h2>A fresh island?</h2><p>This clears only this prototype’s progress saved in your browser.</p>${btn('Reset this demo','confirm-reset')}${btn('Keep my adventure','close','quiet-btn')}`)}
const actions={home:()=>{close();setView('island')},close,details:routeDetails,start,barriers,rest,next,finish:()=>finish(false),simulate:()=>finish(true),collection:()=>{close();setView('collection')},pause:()=>{const b=$('[data-action="pause"]');if(timer){stopTimer();b.textContent='Resume timer'}else{b.textContent='Pause timer';timer=setInterval(()=>{remaining=Math.max(0,remaining-1);tick();if(!remaining){stopTimer();b.disabled=true}},1000)}},'confirm-rest':()=>{if(!state.restDays.includes(state.day)){state.restDays.push(state.day);log('A day to pause','Chose rest. Every discovery stayed in place.')}render();close();toast('Rest chosen. Your island is safe and sound.')},'confirm-reset':()=>{state={day:1,completed:[],events:[],restDays:[]};save();close();setView('island');render();toast('A new beginning. Welcome to your island.')}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route)chooseRoute(b.dataset.route);else if(b.dataset.replay)chooseRoute(b.dataset.replay);else if(b.dataset.barrier)detour(b.dataset.barrier);else if(b.dataset.view)setView(b.dataset.view);else if(b.dataset.action)actions[b.dataset.action]?.()});$('.modal-close').onclick=close;$('#modal').addEventListener('close',stopTimer);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)close()}});$('#rest').onclick=rest;$('#next-day').onclick=next;$('#reset').onclick=reset;$('#map-discover').onclick=()=>setView('collection');$('.brand').onclick=e=>{e.preventDefault();setView('island')};$('#help').onclick=()=>open(`<span class="pill">WELCOME TO REROUTE</span><h2>Find your own way.</h2><p>1. Choose one of today’s three routes.<br>2. Start a timer, or tap “Plans changed” to find a detour.<br>3. Complete your route to grow your island.<br>4. Try a new demo day to build your collection.</p><p>This interactive concept uses predefined suggestions, a real timer, and browser-local progress. It has no AI service, wearable connection, or live health data. “Simulate completion” lets you explore quickly.</p>${btn('Let’s explore →','close')}`);
function renderIsland(){const completed=state.completed.length;const detoured=state.completed.some(x=>x.detour);const tree=(x,y,s=1,c='#66895b')=>`<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="7" rx="15" ry="6" fill="#526d3c" opacity=".1"/><path d="M0 5v-28" stroke="#746a43" stroke-width="4"/><ellipse cy="-30" rx="15" ry="22" fill="${c}"/><ellipse cx="-7" cy="-25" rx="10" ry="15" fill="#94ac6e" opacity=".55"/><path d="M0-9v-26" stroke="#4c7144" stroke-width="1.1" opacity=".3"/></g>`;const pine=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="5" rx="14" ry="5" fill="#567341" opacity=".1"/><path d="M0 7v-25" stroke="#79704d" stroke-width="3"/><path d="M-16-9 0-45 16-9Z" fill="#507459"/><path d="M-13-20 0-51 13-20Z" fill="#6e936b"/><path d="M0-51v42h16Z" fill="#3c624e" opacity=".25"/></g>`;let trees='';[[286,211,1.15],[314,203,.9],[258,231,.85],[362,188,.8],[524,197,.9],[555,215,1.12],[580,233,.72],[502,236,.7],[324,284,.75],[354,299,.7],[590,281,.8],[553,301,.9],[422,169,.64]].forEach(([x,y,s],i)=>trees+=i%3===0?pine(x,y,s):tree(x,y,s,i%2?'#739461':'#5d8458'));$('#island-art').innerHTML=`<svg viewBox="0 0 900 410" role="img" aria-label="Your illustrated island, with ${completed} completed routes. ${detoured?'A wooden detour bridge has been discovered.':'Complete a detour to discover a bridge.'}"><defs><linearGradient id="sea" x2="0" y2="1"><stop stop-color="#eef3e9"/><stop offset="1" stop-color="#e5efe9"/></linearGradient><linearGradient id="land" x1="0" x2="1" y2="1"><stop stop-color="#c9d5a3"/><stop offset="1" stop-color="#abc28d"/></linearGradient><linearGradient id="cliff" x2="0" y2="1"><stop stop-color="#b2ba8f"/><stop offset="1" stop-color="#909e7d"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="10"/></filter><pattern id="water" width="100" height="60" patternUnits="userSpaceOnUse"><path d="M10 20q8 4 16 0m35 20q8 4 16 0" stroke="#c7dcd0" stroke-width="1" fill="none" opacity=".7"/></pattern></defs><rect width="900" height="410" fill="url(#sea)"/><rect x="80" y="100" width="740" height="270" fill="url(#water)"/><ellipse cx="447" cy="311" rx="191" ry="24" fill="#5d8a70" opacity=".1" filter="url(#shadow)"/><path d="M216 248C210 195 291 165 354 164c52-41 147-43 185-9 68 1 119 34 121 81 14 53-58 98-119 103-56 28-110 18-149 3-88 10-164-21-176-56Z" fill="#f4f1d9" opacity=".75"/><path d="M233 240c-10-44 53-74 123-68 50-40 131-47 183-10 57-1 101 34 106 70l-4 34c-10 38-54 62-109 64-51 25-107 14-142-1-67 8-143-15-157-49Z" fill="url(#cliff)"/><path d="M233 240c-10-44 53-74 123-68 50-40 131-47 183-10 57-1 101 34 106 70-1 40-53 67-113 69-51 25-107 14-142-1-67 8-143-15-157-49Z" fill="url(#land)"/><path d="M260 251q-13 22 4 36m28-14 2 25m301-37-7 33m28-55-5 38" stroke="#879873" stroke-width="3" opacity=".45"/><path d="M337 263q40-42 86-38t57 42q23 22 60-7" stroke="#dfe2b6" stroke-width="18" fill="none" stroke-linecap="round"/><path d="M337 263q40-42 86-38t57 42q23 22 60-7" stroke="#f0ebc8" stroke-width="10" fill="none" stroke-linecap="round"/><path d="M421 227q-14-31 13-49" stroke="#e9e6bd" stroke-width="10" fill="none" stroke-linecap="round"/><ellipse cx="467" cy="284" rx="29" ry="13" fill="#8fab7e"/><ellipse cx="466" cy="281" rx="28" ry="12" fill="#a8c8b0"/><path d="M449 280q11-4 22-1m-7 6 12-1" stroke="#cde0ce" stroke-width="1.5" fill="none"/><g>${trees}</g><g transform="translate(411 204)"><ellipse cy="14" rx="25" ry="9" fill="#738258" opacity=".17"/><path d="M-18-2h34v23h-34Z" fill="#f5e7c4"/><path d="m-24 0 24-24L24 0Z" fill="#ae7352"/><path d="m0-24 24 24h-24Z" fill="#93634a"/><path d="M-1 7h9v14h-9Z" fill="#7c7153"/><rect x="-12" y="5" width="7" height="7" rx="1" fill="#99af97"/><path d="M11-14v-17h5v22" fill="#c9b294"/></g><g transform="translate(487 191)"><path d="M0 13v-35" stroke="#867c54" stroke-width="3"/><path d="M0-22 21-18 0-9Z" fill="#bc8254"/></g><g transform="translate(338 251)"><ellipse cy="12" rx="10" ry="4" fill="#76865d" opacity=".3"/><path d="M-4 4v8m8-8v8" stroke="#3e5943" stroke-width="3" stroke-linecap="round"/><rect x="-6" y="-8" width="12" height="15" rx="5" fill="#d18b57"/><circle cy="-13" r="6" fill="#e5c7a1"/><path d="M-8-15q7-12 15 0" fill="#3d6850"/><path d="M-7-14H9" stroke="#3d6850" stroke-width="3"/></g><g fill="#e9e4b5"><circle cx="282" cy="247" r="2"/><circle cx="292" cy="258" r="2"/><circle cx="570" cy="260" r="2"/><circle cx="522" cy="292" r="2"/><circle cx="385" cy="283" r="2"/></g><g transform="translate(710 232)"><path d="M-25 18q17-27 48-6v16q-23 14-48-1Z" fill="#a4b495"/><ellipse cy="13" rx="27" ry="17" fill="#c9d6ab"/>${tree(0,8,.7)}</g><g transform="translate(184 309)"><ellipse cy="6" rx="24" ry="10" fill="#b1c4af"/><ellipse rx="23" ry="10" fill="#d9ddbd"/>${pine(0,-1,.6)}</g><g class="island-path" opacity="${detoured?1:.18}"><path d="m620 246 68-8" stroke="#827155" stroke-width="15"/><path d="m620 242 68-8" stroke="#c4aa7a" stroke-width="13"/><path d="m625 235 1 14m9-16 1 15m9-16 1 15m9-17 1 15m9-16 1 15m9-16 1 14" stroke="#99835d" stroke-width="2"/><path d="m618 231 72-8m-71 27 72-8" stroke="#8c795b" stroke-width="2"/></g><g opacity="${completed?1:.25}" class="island-path"><path d="M540 260q37-7 54-15" stroke="#eee7bd" stroke-width="8" stroke-linecap="round" fill="none"/><circle cx="541" cy="260" r="11" fill="#fffaf0" stroke="#75905f" stroke-width="2"/><text x="541" y="264" text-anchor="middle" fill="#5d7e4c" font-size="12">${completed?'✓':'✧'}</text></g><g class="bobbing" transform="translate(0 0)"><rect x="303" y="131" width="102" height="25" rx="12.5" fill="#fffff4" stroke="#dce3ce"/><text x="354" y="147" text-anchor="middle" fill="#7b8c6b" font-size="8" font-family="sans-serif" letter-spacing="1">THE LITTLE WOODS</text></g><g><rect x="464" y="320" width="112" height="24" rx="12" fill="#fffff4" stroke="#dce3ce"/><text x="520" y="335" text-anchor="middle" fill="#7b8c6b" font-size="8" font-family="sans-serif" letter-spacing="1">A PLACE TO BEGIN</text></g>${detoured?'<g><rect x="651" y="180" width="122" height="25" rx="12" fill="#fff6e5" stroke="#dac9a1"/><text x="712" y="196" text-anchor="middle" fill="#9b784e" font-size="8" font-family="sans-serif" letter-spacing="1">THE DETOUR BRIDGE</text></g>':''}<g fill="none" stroke="#8c9e87" stroke-width="1.3" stroke-linecap="round"><path d="M620 127q4-4 8 0 4-4 8 0M650 111q3-3 6 0 3-3 6 0M253 146q3-3 6 0 3-3 6 0"/></g><g fill="#f9fbf2" opacity=".7"><ellipse cx="218" cy="118" rx="42" ry="9"/><ellipse cx="199" cy="113" rx="21" ry="13"/><ellipse cx="734" cy="133" rx="32" ry="7"/><ellipse cx="724" cy="128" rx="17" ry="12"/></g></svg>`}
